SELECT breakdown_value AS `context.columns.breakdown_value`, tuple(uniq(filtered_person_id), NULL) AS `context.columns.visitors`, tuple(sum(filtered_pageview_count), NULL) AS `context.columns.views`, divide(`context.columns.visitors`.1, sum(`context.columns.visitors`.1) OVER ()) AS `context.columns.ui_fill_fraction` FROM (SELECT s.person_id AS filtered_person_id, s.page_screen_count AS filtered_pageview_count, s.exit_pathname AS breakdown_value, s.session_id AS session_id, s.is_bounce AS is_bounce, s.start_timestamp AS start_timestamp FROM (SELECT events.properties.`$session_id` AS session_id, any(events.person_id) AS person_id, countIf(or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS page_screen_count, max(equals(events.event, '$autocapture')) AS has_autocapture, dateDiff('second', min(toTimeZone(events.timestamp, 'UTC')), max(toTimeZone(events.timestamp, 'UTC'))) AS session_duration, argMinIf(nullIf(toString(events.properties.`$pathname`), ''), toTimeZone(events.timestamp, 'UTC'), or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS entry_pathname, argMaxIf(nullIf(toString(events.properties.`$pathname`), ''), toTimeZone(events.timestamp, 'UTC'), or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS exit_pathname, argMinIf(nullIf(toString(events.properties.`$host`), ''), toTimeZone(events.timestamp, 'UTC'), or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS entry_host, argMaxIf(nullIf(toString(events.properties.`$host`), ''), toTimeZone(events.timestamp, 'UTC'), or(equals(events.event, '$pageview'), equals(events.event, '$screen'))) AS exit_host, fromUnixTimestamp(intDiv(accurateCastOrNull(bitShiftRight(any(toUInt128(toUUIDOrNull(events.properties.`$session_id`))), 80), 'Int64'), 1000)) AS start_timestamp, if(equals(page_screen_count, 0), NULL, not(or(greaterOrEquals(page_screen_count, 2), has_autocapture, greaterOrEquals(session_duration, 10)))) AS is_bounce FROM events_json AS events WHERE and(equals(events.team_id, TEAM_ID), and(isNotNull(toUInt128(toUUIDOrNull(events.properties.`$session_id`))), or(and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0), 1)) GROUP BY session_id HAVING greater(page_screen_count, 0)) AS s) GROUP BY `context.columns.breakdown_value` HAVING isNotNull(`context.columns.breakdown_value`) ORDER BY `context.columns.visitors` DESC, `context.columns.views` DESC, `context.columns.breakdown_value` ASC LIMIT 100
